"""Python engine: SciPy (and statsmodels for regression)."""

from __future__ import annotations

import json
import sys

from .base import EngineAdapter, fill_template

PRELUDE = '''\
#!/usr/bin/env python3
# Generated by aistat __AISTAT_VERSION__ for __RUN_ID__ (__METHOD__).
# Re-run from this folder:  python analysis.py [data.csv] [raw_outputs/results.json]
import json
import math
import platform
import sys

import numpy as np
import pandas as pd
import scipy
from scipy import stats

PLAN = json.loads(__PLAN_JSON__)
DATA = sys.argv[1] if len(sys.argv) > 1 else __DEFAULT_DATA__
OUT = sys.argv[2] if len(sys.argv) > 2 else "raw_outputs/results.json"
V, O = PLAN["variables"], PLAN["options"]
ENGINE_VERSION = [f"Python {platform.python_version()}", f"SciPy {scipy.__version__}", f"pandas {pd.__version__}"]


def clean(x):
    if isinstance(x, dict):
        return {str(k): clean(v) for k, v in x.items()}
    if isinstance(x, (list, tuple)):
        return [clean(v) for v in x]
    if isinstance(x, (bool, np.bool_)):
        return bool(x)
    if isinstance(x, (int, np.integer)):
        return int(x)
    if isinstance(x, (float, np.floating)):
        return float(x) if math.isfinite(x) else None
    return x


def shapiro(values, check_id, label):
    values = np.asarray(values, dtype=float)
    base = {"id": check_id, "label": label, "test": "Shapiro-Wilk", "n": int(len(values))}
    if not 3 <= len(values) <= 5000 or np.ptp(values) == 0:
        return {**base, "statistic": None, "p": None, "violated": None, "note": "樣本數或變異不足，無法檢定"}
    w, p = stats.shapiro(values)
    return {**base, "statistic": float(w), "p": float(p), "violated": bool(p < O["alpha"])}


df = pd.read_csv(DATA, encoding="utf-8", dtype={c: str for c in PLAN.get("string_columns", [])})
statistics, assumptions, warnings = {}, [], []
'''

FOOTER = '''
result = {
    "engine": {"name": "python", "version": "; ".join(ENGINE_VERSION)},
    "method": PLAN["method"],
    "run_id": PLAN["run_id"],
    "n_input_rows": int(len(df)),
    "statistics": statistics,
    "assumptions": assumptions,
    "warnings": warnings,
}
with open(OUT, "w", encoding="utf-8") as f:
    json.dump(clean(result), f, ensure_ascii=False, indent=2, allow_nan=False)
'''

METHOD_CODE = {
    "descriptives": '''
summaries = []
for name in V["variables"]:
    col = df[name]
    valid = col.dropna()
    base = {"name": name, "n": int(len(valid)), "missing": int(col.isna().sum())}
    if name in PLAN["string_columns"]:
        total = len(valid)
        freqs = [{"level": lvl, "count": int((valid == lvl).sum()),
                  "proportion": float((valid == lvl).sum() / total) if total else None}
                 for lvl in PLAN["levels"][name]]
        summaries.append({**base, "kind": "categorical", "frequencies": freqs})
    else:
        x = valid.to_numpy(dtype=float)
        q1, med, q3 = np.percentile(x, [25, 50, 75]) if len(x) else (None, None, None)  # numpy "linear" = R type 7
        summaries.append({**base, "kind": "numeric",
                          "mean": x.mean() if len(x) else None,
                          "sd": np.std(x, ddof=1) if len(x) > 1 else None,
                          "median": med, "q1": q1, "q3": q3,
                          "min": x.min() if len(x) else None, "max": x.max() if len(x) else None})
statistics = {"n_rows": int(len(df)), "variables": summaries}
''',
    "linear-regression": '''
import statsmodels
import statsmodels.api as sm

ENGINE_VERSION.append(f"statsmodels {statsmodels.__version__}")
yv, X = V["outcome"], V["predictors"]
d = df[[yv, *X]].dropna()
y = d[yv].to_numpy(dtype=float)
Xm = d[X].to_numpy(dtype=float)
design = sm.add_constant(Xm, has_constant="add")
if np.linalg.matrix_rank(design) < design.shape[1]:
    sys.exit("預測變項完全共線（perfect collinearity），無法估計迴歸係數；請移除重複或可互相換算的預測變項。")
fit = sm.OLS(y, design).fit()
ci = fit.conf_int(alpha=1 - O["conf_level"])
sd_y = np.std(y, ddof=1)
sd_x = np.std(Xm, axis=0, ddof=1)
coefficients = [
    {"term": term, "b": fit.params[i], "se": fit.bse[i], "t": fit.tvalues[i], "p": fit.pvalues[i],
     "ci_lower": ci[i, 0], "ci_upper": ci[i, 1], "beta": None if i == 0 else fit.params[i] * sd_x[i - 1] / sd_y}
    for i, term in enumerate(["(Intercept)", *X])
]
statistics = {
    "n": len(y), "n_excluded": len(df) - len(y), "k": len(X),
    "coefficients": coefficients,
    "r_squared": fit.rsquared, "adj_r_squared": fit.rsquared_adj,
    "f": fit.fvalue, "df1": int(fit.df_model), "df2": int(fit.df_resid), "f_p": fit.f_pvalue,
    "residual_se": math.sqrt(fit.mse_resid), "conf_level": O["conf_level"],
}
# Breusch-Pagan, Koenker's studentized form: n × R² of squared residuals on the predictors.
aux = sm.OLS(fit.resid ** 2, design).fit()
bp = len(y) * aux.rsquared
assumptions = [
    shapiro(fit.resid, "normality_of_residuals", "殘差常態性"),
    {"id": "homoscedasticity", "label": "殘差變異數同質", "test": "Breusch-Pagan (Koenker)",
     "statistic": bp, "df": len(X), "p": stats.chi2.sf(bp, len(X)), "violated": bool(stats.chi2.sf(bp, len(X)) < O["alpha"])},
]
if len(X) >= 2:
    vifs = []
    for j, term in enumerate(X):
        others = sm.add_constant(np.delete(Xm, j, axis=1), has_constant="add")
        vifs.append({"term": term, "vif": 1 / (1 - sm.OLS(Xm[:, j], others).fit().rsquared)})
    worst = max(v["vif"] for v in vifs)
    assumptions.append({"id": "multicollinearity", "label": "共線性", "test": "VIF", "statistic": worst, "p": None,
                        "threshold": 10, "vif": vifs, "violated": bool(worst >= 10)})
''',
    "correlation": '''
x, y = V["x"], V["y"]
d = df[[x, y]].dropna()
a = d[x].to_numpy(dtype=float)
b = d[y].to_numpy(dtype=float)
n = len(d)
lo = hi = None
if O["method"] == "pearson":
    res = stats.pearsonr(a, b)
    ci = res.confidence_interval(confidence_level=O["conf_level"])
    lo, hi = ci.low, ci.high
    assumptions = [{**shapiro(a, "normality", f"{x} 常態性"), "variable": x},
                   {**shapiro(b, "normality", f"{y} 常態性"), "variable": y}]
else:
    res = stats.spearmanr(a, b)  # p from the t approximation, as R's cor.test(exact = FALSE)
r = float(res.statistic)
statistics = {
    "n": n, "n_excluded": len(df) - n, "method": O["method"],
    "r": r, "t": r * math.sqrt((n - 2) / (1 - r * r)) if abs(r) < 1 else None, "df": n - 2, "p": res.pvalue,
    "ci_lower": lo, "ci_upper": hi, "conf_level": O["conf_level"],
}
''',
    "chi-square": '''
r, c = V["row"], V["column"]
d = df[[r, c]].dropna()
RL, CL = PLAN["levels"][r], PLAN["levels"][c]
obs = np.array([[int(((d[r] == a) & (d[c] == b)).sum()) for b in CL] for a in RL])
chi2, p, dof, exp = stats.chi2_contingency(obs, correction=False)
n = int(obs.sum())
k = min(obs.shape) - 1
below = int((exp < 5).sum())
statistics = {
    "n": n,
    "n_excluded": len(df) - n,
    "row_levels": RL,
    "column_levels": CL,
    "observed": obs.tolist(),
    "expected": exp.tolist(),
    "row_proportions": (obs / obs.sum(axis=1, keepdims=True)).tolist(),
    "chi2": chi2, "df": int(dof), "p": p,
    "cramers_v": math.sqrt(chi2 / (n * k)),
}
assumptions = [{
    "id": "expected_counts", "label": "期望次數足夠", "test": "expected counts",
    "statistic": None, "p": None, "threshold": 5, "max_proportion": 0.2,
    "min_expected": float(exp.min()), "cells_below_threshold": below, "proportion_below_threshold": below / exp.size,
    "violated": bool(below / exp.size > 0.2 or exp.min() < 1),
}]
''',
    "independent-t-test": '''
y, g = V["outcome"], V["group"]
d = df[[y, g]].dropna()
L1, L2 = PLAN["levels"][g]
x1 = d.loc[d[g] == L1, y].to_numpy(dtype=float)
x2 = d.loc[d[g] == L2, y].to_numpy(dtype=float)
n1, n2 = len(x1), len(x2)


def ttest(equal_var):
    r = stats.ttest_ind(x1, x2, equal_var=equal_var)
    ci = r.confidence_interval(confidence_level=O["conf_level"])
    return {"t": r.statistic, "df": r.df, "p": r.pvalue, "ci_lower": ci.low, "ci_upper": ci.high}


pooled_sd = math.sqrt(((n1 - 1) * np.var(x1, ddof=1) + (n2 - 1) * np.var(x2, ddof=1)) / (n1 + n2 - 2))
statistics = {
    "n": n1 + n2,
    "n_excluded": len(df) - (n1 + n2),
    "groups": [{"level": L1, "n": n1, "mean": x1.mean(), "sd": np.std(x1, ddof=1)},
               {"level": L2, "n": n2, "mean": x2.mean(), "sd": np.std(x2, ddof=1)}],
    "mean_diff": x1.mean() - x2.mean(),
    "welch": ttest(False),
    "student": ttest(True),
    "pooled_sd": pooled_sd,
    "cohens_d": (x1.mean() - x2.mean()) / pooled_sd if pooled_sd > 0 else None,
    "conf_level": O["conf_level"],
}
lev = stats.levene(x1, x2, center="median")
assumptions = [
    {**shapiro(x1, "normality_by_group", f"{L1} 組常態性"), "group": L1},
    {**shapiro(x2, "normality_by_group", f"{L2} 組常態性"), "group": L2},
    {"id": "homogeneity_of_variance", "label": "變異數同質性", "test": "Brown-Forsythe Levene",
     "statistic": lev.statistic, "p": lev.pvalue, "df1": 1, "df2": n1 + n2 - 2,
     "violated": bool(lev.pvalue < O["alpha"]), "informational": True},
]
''',
    "paired-t-test": '''
d = df[[V["before"], V["after"]]].dropna()
before = d[V["before"]].to_numpy(dtype=float)
after = d[V["after"]].to_numpy(dtype=float)
diff = after - before
n = len(diff)
res = stats.ttest_rel(after, before)
ci = res.confidence_interval(confidence_level=O["conf_level"])
sd_diff = float(np.std(diff, ddof=1))
statistics = {
    "n": n,
    "n_excluded": len(df) - n,
    "mean_before": before.mean(), "sd_before": np.std(before, ddof=1),
    "mean_after": after.mean(), "sd_after": np.std(after, ddof=1),
    "mean_diff": diff.mean(), "sd_diff": sd_diff, "se_diff": sd_diff / math.sqrt(n),
    "t": res.statistic, "df": res.df, "p": res.pvalue,
    "ci_lower": ci.low, "ci_upper": ci.high, "conf_level": O["conf_level"],
    "cohens_dz": diff.mean() / sd_diff if sd_diff > 0 else None,
}
assumptions = [shapiro(diff, "normality_of_differences", "差值常態性")]
''',
}


class PythonEngine(EngineAdapter):
    name = "python"
    script_name = "analysis.py"
    install_hint = "請安裝 scipy、pandas、statsmodels。"

    def command(self) -> list[str] | None:
        # -I: isolated mode, so files in the run folder cannot shadow library modules.
        return [sys.executable, "-I"]

    def render_script(self, plan: dict, default_data: str) -> str:
        head = fill_template(PRELUDE, plan, PLAN_JSON=repr(json.dumps(plan, ensure_ascii=False)),
                             DEFAULT_DATA=repr(default_data))
        return head + METHOD_CODE[plan["method"]] + FOOTER
